CREATE TABLE IF NOT EXISTS organizations (id VARCHAR(32) PRIMARY KEY, name VARCHAR(100) NOT NULL, parent_id VARCHAR(32));
CREATE TABLE IF NOT EXISTS users (id VARCHAR(80) PRIMARY KEY, auth_number VARCHAR(80) UNIQUE NOT NULL, display_name VARCHAR(100) NOT NULL, role VARCHAR(32) NOT NULL, organization_id VARCHAR(32) NOT NULL REFERENCES organizations(id), active BOOLEAN NOT NULL DEFAULT TRUE, password_hash VARCHAR(512), password_salt VARCHAR(256), must_change_password BOOLEAN NOT NULL DEFAULT TRUE, revision BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS official_records (id VARCHAR(80) PRIMARY KEY, revision BIGINT NOT NULL, dataset VARCHAR(32) NOT NULL, period_key VARCHAR(100) NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, organization_id VARCHAR(32) NOT NULL REFERENCES organizations(id), source_fingerprint VARCHAR(64) NOT NULL, cell_data CLOB NOT NULL, filename VARCHAR(200) NOT NULL, imported_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, legacy_extras CLOB NOT NULL);
CREATE INDEX IF NOT EXISTS idx_records_scope ON official_records(organization_id,dataset,period_start,period_end);
CREATE INDEX IF NOT EXISTS idx_records_fingerprint ON official_records(source_fingerprint);
CREATE TABLE IF NOT EXISTS audit_events (id VARCHAR(80) PRIMARY KEY, event_at VARCHAR(40) NOT NULL, actor_id VARCHAR(80) NOT NULL, actor_name VARCHAR(100) NOT NULL, actor_role VARCHAR(32) NOT NULL, organization_id VARCHAR(32) NOT NULL, record_id VARCHAR(80), action VARCHAR(40) NOT NULL, request_id VARCHAR(100) NOT NULL, before_data CLOB NOT NULL, after_data CLOB NOT NULL, details CLOB NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_scope ON audit_events(organization_id,event_at);
CREATE TABLE IF NOT EXISTS processed_requests (id VARCHAR(100) PRIMARY KEY, actor_id VARCHAR(80) NOT NULL, payload_hash VARCHAR(64) NOT NULL, result_id VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS migration_items (legacy_key VARCHAR(250) PRIMARY KEY, record_id VARCHAR(80) NOT NULL, source_hash VARCHAR(64) NOT NULL);
CREATE TABLE IF NOT EXISTS access_requests (id VARCHAR(80) PRIMARY KEY, auth_number VARCHAR(80) NOT NULL, display_name VARCHAR(100) NOT NULL, organization_id VARCHAR(32) NOT NULL, state VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL, decided_by VARCHAR(80), decision_reason CLOB);
CREATE TABLE IF NOT EXISTS drafts (id VARCHAR(80) PRIMARY KEY, owner_id VARCHAR(80) NOT NULL, organization_id VARCHAR(32) NOT NULL, dataset VARCHAR(32) NOT NULL, payload CLOB NOT NULL, revision BIGINT NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS submissions (id VARCHAR(80) PRIMARY KEY, owner_id VARCHAR(80) NOT NULL, organization_id VARCHAR(32) NOT NULL, dataset VARCHAR(32) NOT NULL, state VARCHAR(32) NOT NULL, payload CLOB NOT NULL, created_at VARCHAR(40) NOT NULL, reviewer_id VARCHAR(80), decided_at VARCHAR(40), decision_reason CLOB);
CREATE TABLE IF NOT EXISTS notification_events (id VARCHAR(80) PRIMARY KEY, event_type VARCHAR(80) NOT NULL, organization_id VARCHAR(32) NOT NULL, payload CLOB NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS notification_receipts (event_id VARCHAR(80) NOT NULL REFERENCES notification_events(id), user_id VARCHAR(80) NOT NULL, read_at VARCHAR(40), PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS security_acknowledgements (id VARCHAR(80) PRIMARY KEY, user_id VARCHAR(80) NOT NULL, session_id VARCHAR(100) NOT NULL, notice_version VARCHAR(80) NOT NULL, accepted_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS import_batches (id VARCHAR(80) PRIMARY KEY, actor_id VARCHAR(80) NOT NULL, dataset VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL, added_count INT NOT NULL, duplicate_count INT NOT NULL, preserved_count INT NOT NULL);
